    if (back) { await gkTeleportInner({ text: back, exact: true, noRoute: true }, `${why}: ${back}`); moved = Math.hypot(Me.X - start.x, Me.Y - start.y) > 1500; }
    if (!moved && !currentTownKey()) { lastTownCmd = 0; moved = await townCommand(`${why}: no '${wanted.text}' at this gatekeeper`); }
    if (moved) return gkTeleport({ ...wanted, escaped: true }, why);
