    if (abort() || Me.IsDead) return null;
    await walkDirect(a.x, a.y, a.z, 120, 15000, abort, 'route');
    const w = { x: Math.round(a.x + Math.cos(ang) * len * 0.2 + Math.cos(ang + Math.PI / 2) * off),
                y: Math.round(a.y + Math.sin(ang) * len * 0.2 + Math.sin(ang + Math.PI / 2) * off), z: Math.round(a.z || Me.Z) };
