/** Lederens gåtur som hold: stykker á ~1500, vent på alle ved hvert checkpoint, alle følger lederen. */
async function leadTeamWalk(x, y, z, dist, timeoutMs, abort) {
  if (await refuseTownExit(x, y, z, 'team walk')) return false;
  const g = CONFIG.together;
  const until = now() + timeoutMs;
  App.emit('swarm.together.follow', { leader: Me.Name });
  intent('lead team', `to ${P(x, y, z)} with ${teamNames().join(', ')}`, { x, y, z });
  await waitForTeamHere('start', abort);
  // the wall-aware route first, the whole team waits at a checkpoint every stageDist ALONG the route (not along a straight line)
  {
    let lastStop = 0;
    state.noTeamWalk = true;
    let gw;
    try {
      gw = await geoWalk(x, y, z, dist, Math.min(timeoutMs, 600000), abort, async (walked) => {
        if (walked - lastStop < g.stageDist) return true;
        lastStop = walked;
        await waitForTeamHere(`on the way to ${P(x, y)}`, abort);
        return !(leadMode() && leftBehind.size) && !(abort && abort());
      });
    } finally { state.noTeamWalk = false; }
    if (gw === true) { await waitForTeamHere(`at ${P(x, y)}`, abort); intentDone('lead team', true, 'whole team arrived (wall-aware route)'); return true; }
    if (gw === false && ((abort && abort()) || Me.IsDead || (leadMode() && leftBehind.size))) { intentDone('lead team', false, 'stopped'); return false; }
  }
  let best = distTo(x, y), fails = 0;            // no way through (2026-10-04: Crafter1 walked into a wall at the Coal Mines landing for 9+ min)
  while (now() < until && !Me.IsDead) {
    const d = distTo(x, y);
    if (d <= dist) break;
    if (d < best - 500) { best = d; fails = 0; }
    if (fails >= 3) { note(`leader: no way through to ${P(x, y)} (3 legs without progress, ${Math.round(d)} left) — giving this spot up`, true); break; }
    if (abort && abort()) return false;
    if (leadMode() && leftBehind.size) { intentDone('lead team', false, 'someone was left behind: regroup in Giran'); return false; }
    // teleported away mid-walk (fx the restock trip took the party to Giran) or the restock flow has the party: stop at once
    if (d > CONFIG.travel.maxWalk || partyTripBusy) { note(`leader: stopped the team walk to ${P(x, y)} — ${partyTripBusy ? 'restock trip has the party' : Math.round(d / 1000) + 'k away now (teleported)'}`, true); intentDone('lead team', false, 'stopped'); return false; }
    const step = Math.min(d, g.stageDist);
    const a = Math.atan2(y - Me.Y, x - Me.X);
    const sx = d <= g.stageDist ? x : Math.round(Me.X + Math.cos(a) * step), sy = d <= g.stageDist ? y : Math.round(Me.Y + Math.sin(a) * step);
    state.noTeamWalk = true;
    let ok;
    try { ok = await walkToInner(sx, sy, z || Me.Z, d <= g.stageDist ? dist : g.stageArrive, Math.min(until - now(), 120000), abort); } finally { state.noTeamWalk = false; }
    await waitForTeamHere(`on the way to ${P(x, y)}`, abort);
    if (!ok && distTo(sx, sy) > 600) { fails++; note(`leader: stuck heading to ${P(sx, sy)} — trying another way (${fails}/3)`); }
  }
  const r = distTo(x, y) <= dist;
  intentDone('lead team', r, r ? 'whole team arrived' : `${Math.round(distTo(x, y))} left`);
  return r;
}
