const isSaWeapon = (name) => / - /.test(String(name || '')) && !/^Common Item/.test(String(name || ''));
/** The highest grade my level allows (NONE, D at 20, C at 40, …). */
function myGearGrade() { let g = 'NONE'; GEAR_GRADES.forEach(x => { if (gradeOk(x)) g = x; }); return g; }
// GEARPREF-BEGIN (gear planner, user 2026-10-09: the wanted item per slot for EVERY class + grade, dashboard #/gear) — pure helpers,
// tested offline by docs/plan/tools/test_gear_prefs.js. gear_prefs.json keeps the old per-role entries { role: { grade: { slot: itemId,
// _weapon } } } and adds "_class": { classId: { grade: { slot: { id, alt: [ids in order], buy: auto|real|common, name, src }, _fallback } } }
