    GEARPREF_SLOTS.forEach(s => { if (!out[s] && g[s] != null) { const e = gearPrefEntry(g[s], 'class ' + cid); if (e) out[s] = e; } });
    if (out._fallback == null && (g._fallback === 'keep' || g._fallback === 'auto')) out._fallback = g._fallback;
