/** Forsyninger til en mission: hvem skal have hvad (oven på normal restock). */
function missionSupplies(kind) {
  const m = CONFIG.mission.supplies;
  const role = state.role;
  const out = [].concat(m.all || []);
  if (CONFIG.buffs.raidCasterRoles.includes(role) || /healer|bishop|shilliensaint|necromancer|nuker|doomcryer/.test(role)) out.push(...(m.caster || []));
  if (role === 'sk') out.push(...(m.tank || []));
  return kind === 'raid' ? out : (m.all || []);
}

const missionState = { prev: null };

/** Mission-handlinger i teamAction. */
async function missionTeamAction(action, data) {
  if (action === 'pause') {
    missionState.prev = { mode: state.mode, quest: questRun.active ? { id: questRun.quest && questRun.quest.id, leg: questRun.leg } : null };
    if (questRun.active) questRun.stop = true;
    stopCombatG();
    state.mode = 'mission';
    return { ok: true, msg: `paused (${missionState.prev.quest ? 'quest ' + missionState.prev.quest.id : missionState.prev.mode})` };
  }
  if (action === 'supply') {
    const extra = missionSupplies(data.kind).map(s => ({ ...s, have: itemCount(s.id) }))
      .map(s => ({ ...s, buy: Math.max(0, s.want - s.have) })).filter(s => s.buy > 0);
    if (!extra.length) return { ok: true, msg: 'have supplies' };
    const r = CONFIG.restock;
    const npc = await findNpcOrWalk(n => r.npcMatch.test(`${n.Title} ${n.Name}`) && !r.skipNpcs.includes(n.Name),
                                    grocerSpawns().concat(r.knownNpcs), r.walkTimeoutMs);
    if (!npc) return { ok: false, msg: 'no Grocer for supplies' };
    const res = await buyAt(npc, extra.map(s => ({ id: s.id, name: s.name, count: s.buy })), 'mission');
    return { ok: res.ok, msg: res.msg };
  }
  if (action === 'deliver') {
    return { ok: true, msg: 'hand-in: waiting for clan warehouse / bank character (not built yet)' };
  }
  if (action === 'engage') {
    const b = data.boss;
    combatSquare(CONFIG.mission.engageRadius * zoneScale(), b.x, b.y, b.z);
    if (!IsEnabled) EnableBot();
    startCombatG();
    let t = null;
    try { t = findMobByName(b.name, 3000); } catch (e) { }
    state.bossName = b.name; state.mode = 'raid'; raidCtl.aggroAt = 0; raidCtl.focus = 0; raidCtl.engaged = !!data.engaged;
    lootSnapshot(b.name);
    if (t) runRaidSequence().catch(e => logError('raid sequence', e));   // tank first, focus minions, behind the boss, healers heal
    else {
      // SELU "lost" (2026-10-07 20:47-20:50): the boss was more than 3000 from the TANK at the engage step, so the tank's raid sequence never
      // started (no pull, no damage on the boss for 3 min, then 'lost'). Not visible yet -> keep looking (max 2 min) and start the sequence
      // the moment it is within 3000; the raid must still be on (same boss, raid mode).
      const want = b.name, t0 = now();
      (async () => {
        while (now() - t0 < 120000 && state.mode === 'raid' && state.bossName === want && !Me.IsDead) {
          await sleep(1000);
          let s = null; try { s = findMobByName(want, 3000); } catch (e) { }
          if (s && !s.IsDead) { note(`raid ${want}: boss in sight now (${Math.round(Distance(s))} away) — starting my raid part`); runRaidSequence().catch(e => logError('raid sequence', e)); return; }
          // the tank walks up to ~1500 of a boss he sees further away (raid bosses are not aggressive; a straight server move, no path search)
          if (/^(sk|tank)$/.test(state.role || '') && now() - t0 > 3000 && (now() - t0) % 6000 < 1100) {
            let f = null; try { f = findMobByName(want, 7000); } catch (e) { }
            if (f && !f.IsDead) { const d = Math.hypot(f.X - Me.X, f.Y - Me.Y), k = Math.max(0, d - 1500) / (d || 1); try { Send.MoveBackwardToLocation(Math.round(Me.X + (f.X - Me.X) * k), Math.round(Me.Y + (f.Y - Me.Y) * k), Math.round(f.Z)); } catch (e) { } }
          }
        }
      })().catch(e => logError('raid sequence wait', e));
    }
    return { ok: true, msg: t ? `raid: engaging ${t.Name} (tank first)` : `${b.name} not visible yet — fighting in the zone` };
  }
  if (action === 'kamarebuff') {                // instansen fjernede buffs
    const ok = await buffSelf('kamaloka', true);
    return { ok, msg: ok ? `${longBuffCount()} buffs` : 'board not working in the instance?' };
  }
  if (action === 'kamaclear') {
    const r = leadMode() ? await instanceFight(data.boss, CONFIG.mission.kamalokaTimeoutMs) : await clearInstance(data.boss, CONFIG.mission.kamalokaTimeoutMs);
    return { ok: r === 'cleared', msg: r };
  }
  if (action === 'resume') {
    state.mode = 'idle';
    const p = missionState.prev;
    if (p && p.quest && p.quest.id) {
      const q = pickQuest(p.quest.id);
      if (q) runQuest(q, p.quest.leg || 0).catch(e => logError('quest resume', e));
      return { ok: true, msg: `resuming quest ${p.quest.id}` };
    }
    return { ok: true, msg: 'ready (no previous activity to resume)' };
  }
  return null;
}

