// ---------------------------------------------------------------------------------------------------------------------------------
// WAREHOUSE STASH (user 2026-10-09 16:05: "warehouse deposit for Dagger1's materials (185 stacks that fill his bag)", all accounts).
// What does not belong in the bag (crafting materials unless I am the crafter, recipes I cannot use, seal stones, ancient adena, L2Day
// letters, old gear nobody plans and the shop does not buy) goes into my PRIVATE warehouse at Taurin, Giran (recorded route
// 'warehouse' in Scripts/data/giran_routes.json). Supply-run step 'stash' (bag > CONFIG.stash.above slots, one after another), !stash
// [name] (now), !stashplan [name] (dry run -> Logs/stash_plan_<name>.json). Log: Logs/stash.log + the intent log; record of what is in the
// warehouse: Logs/stash_<name>.json (dashboard character page). User rules (read live): Scripts/data/stash_rules.json.
// PACKETS (verified in L2Swarm's own packet table Data/base.db -> PacketsGSClient / PacketsGSServer, 2026-10-09):
//   client 3B SendWareHouseDepositList = d(count) count x [d(ObjectID) q(Count)]   (little-endian, sent with Send.SendHex WITHOUT spaces
//            like the shop packets 37/40 — Send.RequestSellItem with a JS array was ignored, so the host Send.WareHouseDepositList(L2Item[])
//            is only the fallback)
//   server 41 WareHouseDepositList = h(WhType) q(PlayerAdena) h(count) [item ...] -> OnWareHouseDepositList(items) = what the server
//            lets me deposit (anything else in the packet makes the server drop the WHOLE packet: L2J checkItemManipulation)
//   L2J H5 SendWareHouseDepositList: the warehouse keeper must be my last NPC and within interaction range (150), fee 30 adena per item
//   in the packet, capacity: system message 1036 "You have exceeded the quantity that can be inputted." (130 / 874 = full),
//   279 "You do not have enough adena.", 162 "You have moved too far away from the warehouse to perform that action."
//   (L2J defaults: 100 warehouse slots, dwarves 120, clan 150; a stackable kind already in the warehouse takes no new slot.)
// STASH-PURE-BEGIN (no host calls in here: docs/plan/tools/test_stash.js runs this block in node)
const STASH_SEAL = [6360, 6361, 6362], STASH_AA = 5575;
const STASH_KEEP_RE = /Soulshot|Spiritshot|Potion|Elixir|Antidote|Herb|Scroll of Escape|Scroll of Resurrection|Scroll: Recovery|Teleport|Bandage|Dressing|Mana Drug|Healing Drug|Scroll: Enchant|Soul Crystal|Arrow|Bolt|Waking Scroll|Blessed Scroll/i;
const STASH_MSG = { full: [130, 874, 1036, 1859], adena: [279], far: [162] };
/** One bag entry -> { act: 'deposit' | 'keep' | 'sell', why, cat }. it = { id, objId, name, count, equipped, quest, stackable, gear, upgrade,
 *  spare, teamWants, sell }; ctx = { name, crafter, createLvl, commonLvl, keepIds[], stonesToPriest, hasTeam, rules, data }. */
function stashClassify(it, ctx) {
  const id = Number(it.id), name = String(it.name || ''), R = (ctx && ctx.rules) || {}, me = (R.chars && R.chars[ctx.name]) || {};
  const has = (arr) => Array.isArray(arr) && arr.some(x => Number(x) === id);
  const nameRe = (arr) => Array.isArray(arr) && arr.some(s => { try { return new RegExp(s, 'i').test(name); } catch (e) { return false; } });
  const K = (why, cat) => ({ act: 'keep', why, cat: cat || 'keep' }), D = (why, cat) => ({ act: 'deposit', why, cat });
  if (it.equipped) return K('equipped', 'equipped');
  if (it.quest) return K('quest item', 'quest');
  if (id === 57) return K('adena', 'adena');
  if (has(me.keep) || nameRe(me.keepNames)) return K('rule: keep (this character)', 'rule');
  if (has(me.deposit) || nameRe(me.depositNames)) return D('rule: deposit (this character)', 'rule');
  if (has(R.keep) || nameRe(R.keepNames)) return K('rule: keep', 'rule');
  if (has(R.deposit) || nameRe(R.depositNames)) return D('rule: deposit', 'rule');
  if ((ctx.keepIds || []).some(x => Number(x) === id)) return K('consumable I use', 'use');
  if (it.sell) return { act: 'sell', why: 'marked for sale / junk (the sale step sells it)', cat: 'sell' };
  if (STASH_SEAL.includes(id)) return ctx.stonesToPriest ? K('seal stone for the Priest of Dawn (competition, signed up)', 'seal') : D('seal stone', 'seal');
  if (id === STASH_AA) return D('ancient adena', 'aa');
  if ((id >= 3875 && id <= 3888) || /^L2Day - /i.test(name)) return D('L2Day letter (event item)', 'event');
  const data = ctx.data || {}, rec = data.recipes && data.recipes[id];
  if (rec || /^Recipe:/i.test(name)) {
    const lv = rec ? Number(rec[0]) : 99, sk = Number(rec && rec[1] === 'c' ? ctx.commonLvl : ctx.createLvl) || 0;
    if (ctx.crafter && sk >= lv) return K(`recipe I can use (craft level ${lv}, mine ${sk})`, 'recipe');
    return D(ctx.crafter ? `recipe above my craft level (${lv} > ${sk})` : 'recipe I cannot use (not the crafter)', 'recipe');
  }
  if (STASH_KEEP_RE.test(name)) return K('consumable', 'use');
  const mat = data.materials && data.materials[id];
  if (mat && !it.gear) {
    const dw = mat[0] !== null && mat[0] !== undefined && (Number(ctx.createLvl) || 0) >= Number(mat[0]);
    const cm = mat[1] !== null && mat[1] !== undefined && (Number(ctx.commonLvl) || 0) >= Number(mat[1]);
    if (ctx.crafter && (dw || cm)) return K('material for my recipes', 'material');
    return D(ctx.crafter ? 'material above my craft level' : 'crafting material', 'material');
  }
  if (it.gear) {
    if (it.upgrade) return K('an upgrade for me', 'gear');
    if (it.spare) return K('spare gear the planner uses (HP swap)', 'gear');
    if (it.teamWants && ctx.hasTeam) return K('a teammate can use it (the unload hands it over)', 'gear');
    return D('old gear (no upgrade, nobody plans it, not sold)', 'gear');
  }
  return K('unknown kind (add a rule in Scripts/data/stash_rules.json)', 'unknown');
}
/** The whole bag -> { deposit[], keep[], sell[], byCat{} } (rows: objId, id, name, count, stackable, why, cat). */
function stashPlan(items, ctx) {
  const out = { deposit: [], keep: [], sell: [], byCat: {} };
  (items || []).forEach(it => {
    const c = stashClassify(it, ctx);
    const row = { objId: Number(it.objId), id: Number(it.id), name: String(it.name || ''), count: Math.max(1, Number(it.count) || 1), stackable: !!it.stackable, why: c.why, cat: c.cat };
    if (c.act === 'deposit') { out.deposit.push(row); out.byCat[c.cat] = (out.byCat[c.cat] || 0) + 1; }
    else if (c.act === 'sell') out.sell.push(row); else out.keep.push(row);
  });
  return out;
}
/** Deposit order: stackable kinds already in the warehouse first (no new slot), then other stackables, then single pieces. */
function stashOrder(rows, whKinds) {
  const K = whKinds || {}, rank = (r) => (r.stackable && K[r.id] ? 0 : r.stackable ? 1 : 2);
  return (rows || []).slice().sort((a, b) => rank(a) - rank(b) || String(a.cat).localeCompare(String(b.cat)) || String(a.name).localeCompare(String(b.name)));
}
/** New warehouse slots these rows take. */
function stashSlotsNeeded(rows, whKinds) {
  const K = whKinds || {}, seen = {}; let n = 0;
  (rows || []).forEach(r => { if (r.stackable) { if (!K[r.id] && !seen[r.id]) { seen[r.id] = 1; n++; } } else n++; });
  return n;
}
function stashBatches(rows, size) { const out = [], s = Math.max(1, Number(size) || 1); for (let i = 0; i < (rows || []).length; i += s) out.push(rows.slice(i, i + s)); return out; }
function stashLe(v, bytes) { let n = BigInt(v), s = ''; for (let i = 0; i < bytes; i++) { s += Number(n & 0xFFn).toString(16).padStart(2, '0').toUpperCase(); n >>= 8n; } return s; }
/** SendWareHouseDepositList 0x3B: d(count) count x [d(objectId) q(count)], hex WITHOUT spaces (Send.SendHex). */
function stashHex(rows) {
  let hex = '3B' + stashLe(rows.length, 4);
  rows.forEach(r => { hex += stashLe(r.objId, 4) + stashLe(r.count, 8); });
  return hex;
}
/** SendWareHouseWithDrawList 0x3C (same layout) — for a later withdraw; not used yet. */
function stashWithdrawHex(rows) { return '3C' + stashHex(rows).slice(2); }
/** A system message after the packet: 'full' | 'adena' | 'far' | '' */
function stashSysVerdict(id) { id = Number(id) || 0; for (const k of Object.keys(STASH_MSG)) if (STASH_MSG[k].includes(id)) return k; return ''; }
/** Pick the dialog link: private -> "Deposit ... (Private Warehouse)" > "Deposit" without clan > a "Private/Personal Warehouse" sub menu;
 *  clan -> "Deposit ... Clan" > a "Clan Warehouse" sub menu. Never withdraw / freight / quest / sort links. */
function stashPickLink(links, kind) {
  const L = (links || []).filter(l => l && l.cmd && !/withdraw|sort|freight|package|quest|clan hall|castle|cancel|back|close|manor/i.test(String(l.text || '')));
  const t = (l) => String(l.text || '');
  if (kind === 'clan') return L.find(l => /deposit/i.test(t(l)) && /clan/i.test(t(l))) || L.find(l => /clan/i.test(t(l)) && /warehouse/i.test(t(l))) || null;
  return L.find(l => /deposit/i.test(t(l)) && /private|personal/i.test(t(l))) || L.find(l => /deposit/i.test(t(l)) && !/clan/i.test(t(l)))
    || L.find(l => /private|personal/i.test(t(l)) && !/clan/i.test(t(l))) || L.find(l => /warehouse/i.test(t(l)) && !/clan/i.test(t(l))) || null;
}
/** Should the bag be stashed now? (the supply-run step: more than `above` slots, at most every gapMs unless forced) */
function stashDue(bagCount, above, lastAt, t, gapMs, force) { return !!force || (Number(bagCount) > Number(above) && (Number(t) - (Number(lastAt) || 0)) >= (Number(gapMs) || 0)); }
/** Rows that really left the bag: before/after = { objId: count }. */
function stashLeft(rows, before, after) { return (rows || []).filter(r => (Number((after || {})[r.objId]) || 0) < (Number((before || {})[r.objId]) || 0)); }
/** Add deposited rows to the record of what is in the warehouse: rec.kinds { id: { n, c, s, k } } + rec.slotsUsed. */
function stashRecordAdd(rec, rows, at) {
  rec.kinds = rec.kinds || {};
  (rows || []).forEach(r => {
    const k = rec.kinds[r.id] = rec.kinds[r.id] || { n: r.name, c: 0, s: r.stackable ? 1 : 0, k: 0 };
    k.c += Number(r.count) || 1; if (!r.stackable) k.k += 1; k.at = at || k.at;
  });
  rec.slotsUsed = Object.keys(rec.kinds).reduce((a, id) => a + (rec.kinds[id].s ? 1 : Math.max(1, rec.kinds[id].k || 1)), 0);
  return rec;
}
/** One line for party chat / logs. */
function stashLine(done, keeper, fee, extra) {
  const names = (done || []).map(r => `${r.name}${r.count > 1 ? ' x' + r.count : ''}`);
  return `stash: deposited ${(done || []).length} kinds (${names.slice(0, 12).join(', ')}${names.length > 12 ? ', +' + (names.length - 12) + ' more' : ''}) at ${keeper || '?'}, fee ${fee || 0}${extra ? ' — ' + extra : ''}`;
}
function stashPlanLine(p) {
  const cats = Object.keys(p.byCat || {}).map(k => `${k} ${p.byCat[k]}`).join(', ');
  const unk = (p.keep || []).filter(r => r.cat === 'unknown').length;
  return `${(p.deposit || []).length} kinds to deposit (${cats || '-'}), keep ${(p.keep || []).length}${unk ? ` (${unk} unknown kinds kept)` : ''}, ${(p.sell || []).length} for sale`;
}
