          if (got) return { ok: true, msg: `clan ${name} created`, name: got.startsWith('(') ? name : got };
          if (/already exists|is already|in use|taken/i.test(said)) { clanLog(`the name "${name}" is taken`); return { ok: false, taken: true, msg: `name ${name} is taken` }; }
          if (/wait|days|penalt/i.test(said)) return { ok: false, msg: `clan creation penalty: ${said}` };
          if (/criteria|level/i.test(said)) return { ok: false, msg: `server refused: ${said}` };
