  const sp = num(Me.SP || 0), ad = itemCount(57), missing = [];
  const items = (L.items || []).map(i => ({ id: i.id, name: i.name, need: num(i.count || 1), have: itemCount(i.id), source: L.itemSource || '' }));
  if (sp < num(L.sp)) missing.push(`SP ${sp.toLocaleString()} / ${num(L.sp).toLocaleString()}`);
  if (ad < num(L.adena)) missing.push(`adena ${ad.toLocaleString()} / ${num(L.adena).toLocaleString()}`);
  items.forEach(i => { if (i.have < i.need) missing.push(`${i.name} (${i.id}) ${i.have}/${i.need}${i.source ? ' — ' + i.source : ''}`); });
  if (num(L.reputation) && (clanIntel.rep == null || num(clanIntel.rep) < num(L.reputation))) missing.push(`reputation ${num(clanIntel.rep)} / ${num(L.reputation)}`);
