/** The safe trip to a village master (as the clan founding): stop leveling, here or Giran (Gesto / Kusto / Angus), run fn(npc). */
async function atVillageMaster(why, fn) {
  const gen = takeControl(why, PRIO.ORDER);
  if (gen === false) return `busy with something more important (${control.owner}) — try again later`;
  const followWas = (() => { try { return Options.ActiveFollow; } catch (e) { return null; } })();
  try {
    if (autoLvl.active) { autoLvl.stop = true; const t0 = now(); while (autoLvl.active && now() - t0 < 60000) await sleep(1000); }
    try { Options.ActiveFollow = false; } catch (e) { }
    stopCombatG();
    const tried = [];
    for (const npc of villageMastersNear(2500)) { tried.push(String(npc.Name)); const r = await fn(npc); if (r) return r; }
    if (currentTownKey() !== 'Giran') {
      if (isLeader() && teamNames().length) await leadGoGiran(why); else { lastTownCmd = 0; await townCommand(why, 'Giran'); }
      await sleep(4000); sendAppearing(why);
    }
    if (currentTownKey() !== 'Giran') return 'could not get to Giran';
    for (const m of GIRAN_MASTERS) {
      if (interrupted(gen)) return 'interrupted by a more important task';
      if (tried.includes(m.name)) continue;
      if (m.route) { try { await giranGo(m.route); } catch (e) { } }
      if (Math.hypot(m.at[0] - Me.X, m.at[1] - Me.Y) > 600) await walkTo(m.at[0], m.at[1], m.at[2], 150, 90000);
      await sleep(800);
      const here = villageMastersNear(2500).filter(n => String(n.Name) === m.name);
      if (!here.length) { clanLog(`${m.name} not in sight at ${Math.round(Me.X)},${Math.round(Me.Y)}`); continue; }
      tried.push(m.name); const r = await fn(here[0]); if (r) return r;
    }
    return `no village master did it (tried ${tried.join(', ') || 'none'}) — see Logs/clan_page_*.html`;
  } finally {
    try { if (followWas !== null) Options.ActiveFollow = followWas; } catch (e) { }
    releaseControl(why);
  }
}
async function clanLevelUp(why) {
  const N = clanLevelNeeds();
  if (!N) return 'not in a clan';
  if (!N.ok) { const m = `clan level ${N.level} -> ${N.next || '?'}: missing ${N.missing.join('; ')}`; clanLog(m); return m; }
  clanLog(`clan level ${N.level} -> ${N.next} (${why}): everything there — going to a village master`);
  const before = N.level;
  const r = await atVillageMaster('clan level up', async (npc) => {
    const a = await villageMasterClick(npc, [/increase.*(clan|level)|(clan|pledge).*level ?up|level up|raise.*level|upgrade.*clan/i], 'levelup');
    if (!a.ok) { clanLog(a.msg); return null; }                            // next village master
    let html = a.html, said = a.sys;
    // a confirm page ("Do you want to increase...?" -> Yes / Increase)
    for (let i = 0; i < 2 && html; i++) {
      a.save(html);
      // 2026-10-08 06:34: L2Toggle's confirm is a BUTTON "Level Up" (bypass -h 01, next to "Cancel") on the requirements page, and npcLinks()
      // reads <a> links only -> the clan stayed level 0. Links + buttons; "level up" counts as the confirm (the first click was the
      // "Increase Clan Level." LINK, so this cannot level twice: one click per page, and the loop stops as soon as the level rose)
      const L = npcLinks(String(html)).concat((() => { const o = []; const re = /<button[^>]*value="([^"]*)"[^>]*action="bypass\s+([^"]+)"|<button[^>]*action="bypass\s+([^"]+)"[^>]*value="([^"]*)"/gi; let m; while ((m = re.exec(String(html)))) o.push({ cmd: cleanBypass(m[2] || m[3]), text: htmlText(m[1] || m[4] || '') }); return o; })());
      const yes = L.find(l => /^(yes|ok|confirm|accept|level ?up)\b/i.test(l.text));   // only a real confirm: never "Increase" again (could level twice)
      if (!yes || myClanLevel() > before) break;
      clanLog(`${npc.Name}: levelup confirm: click "${yes.text}"`);
      const t0 = now(); const pg = waitNpcHtml(5000); Send.ReqBypassToServer(yes.cmd, true); html = await pg; await sleep(800);
      if (lastSysMsg && lastSysMsg.at >= t0) said = lastSysMsg.text;
    }
    await sleep(1500); await clanIntelRequest('after level up');
    const now2 = clanLevelNow();
    const txt = htmlText(String(html || '')).slice(0, 200);
    if (now2 > before) {
      try { const c2 = clanCfg(); if (c2 && c2.clan) { c2.clan.level = now2; File.WriteAllText(`${__DIR__}\\Scripts\\data\\clan_quests.json`, JSON.stringify(c2, null, 2)); } } catch (e) { }
      const m = `clan level ${before} -> ${now2} at ${npc.Name}${said ? ' — ' + said : ''}`; clanLog(m); return m;
    }
    const m = `level-up clicked at ${npc.Name} but the clan is still level ${now2}${said ? ' — server: ' + said : ''}${txt ? ' — page: ' + txt : ''}`; clanLog(m); return m;
  });
  return r;
}
const CLAN_AUTO_F = `${__DIR__}\\Logs\\clan_auto.json`;
function clanAutoOn() { try { return !!JSON.parse(File.ReadAllText(CLAN_AUTO_F)).levelUp; } catch (e) { return false; } }
const clanLvlRun = { busy: false, last: 0 };
setInterval(async () => {
  try {
    if (clanLvlRun.busy || !IsCharacterReady() || Me.IsDead || !clanAutoOn() || now() - clanLvlRun.last < 15 * 60000) return;
    const ci = clanInfo(); if (!ci || ci.isLeader !== true || !currentTownKey() || control.owner || inRaid() || IsInCombat || state.mode === 'mission') return;
    const N = clanLevelNeeds(); if (!N || !N.ok) return;
    clanLvlRun.busy = true; clanLvlRun.last = now();
    try { note(`clan level (auto): ${await clanLevelUp('auto')}`, true); } finally { clanLvlRun.busy = false; }
  } catch (e) { clanLvlRun.busy = false; }
}, 60000);

// CLAN LEVEL QUESTS: step plans in Scripts/data/clan_quests.json levelQuests.<bloodmark|501|503>.steps (from the L2J datapack scripts).
// Step kinds: talk (go to an NPC, click links by text — automated), hunt (a party farms a spot until an item shows up — automated with the
// existing forced hunting spot), levelup (!clanlevel), manual (the user / several characters; shown, not automated). Progress per step in
// Logs/clanquest_<id>.json { steps: { <n>: { status, at, msg } } }. "!clanquest <id>" runs the NEXT automated step that is not done; for a
// hunt step it must be sent to the party that hunts (the dashboard does that). "!clanquest <id> <n>" runs step n, "!clanquest <id> reset".
function clanQuestPlan(id) { const c = clanCfg(); return c && c.levelQuests ? c.levelQuests[String(id)] || null : null; }
