const SS_STATE_F = `${__DIR__}\\Logs\\sevensigns_state.json`;
function dawnLog(msg) { try { appendShared(`${__DIR__}\\Logs\\dawn.log`, `${new Date().toISOString()} [${Me.Name}] ${msg}\r\n`); } catch (e) { } }
