  const { off } = formationOffset();
  const base = Math.hypot(c.x - T.X, c.y - T.Y) < 40 ? Math.atan2(Me.Y - T.Y, Me.X - T.X) : Math.atan2(c.y - T.Y, c.x - T.X);
