// who hits which teammate (all the time since 2026-10-05 21:30: the tank's aggro spam takes monsters off teammates everywhere); pruned to 1 min
App.on('swarm.attacked', (e) => { try { if (e.data) { inst.attackers[e.data.attacker] = { at: now(), on: e.data.name };
  if (Object.keys(inst.attackers).length > 150) Object.keys(inst.attackers).forEach(k => { if (now() - inst.attackers[k].at > 60000) delete inst.attackers[k]; }); } } catch (er) { } });
function instMove(x, y, z) { try { Send.MoveBackwardToLocation(Math.round(x), Math.round(y), Math.round(z || Me.Z)); } catch (e) { } }
// DEAD INSIDE A KAMALOKA (user 2026-10-05 22:12 "the SE can res Doombringer1" — Doombringer1 had already respawned in Dion after 90 s and was out of
// the run): inside the instance a dead teammate never goes to town while someone is still alive in there; he waits (max 20 min) for a res.
// inst.on ends for a dead member (his fight loop returns), so "inside" = deep underground within an hour of the last fight loop, run not over.
function inKamaInstance() { return num(Me.Z) < -7000 && now() - (inst.lastOnAt || 0) < 3600000 && !inst.ended; }
function instMateAlive() { return teamNames().some(n => { const p = partyMember(n), lp = livePos[n] || {}; const dead = lp.at && now() - lp.at < 10000 ? lp.IsDead : (p && p.IsDead); const x = p ? p.X : lp.X, y = p ? p.Y : lp.Y; return !dead && x != null && Math.hypot(x - Me.X, y - Me.Y) < 9000; }); }
// STICK TOGETHER (user 2026-10-05 21:20, during the first Labyrinth 39 run): everyone stays within INST_TIGHT of the team's spot (the anchor).
// The leader only pulls monsters within INST_PULL of the spot, moves the spot in short steps and waits for the whole team at every new spot
// before the next pull; melee only hits the focus when it is near the spot; casters/healers back off from monsters but never beyond the leash.
const INST_TIGHT = 700, INST_PULL = 1100, INST_LEASH = 1000, INST_WAIT_MS = 20000;
