      if (needsBuff()) { try { await buffSelf('kamaloka: room rest', true); } catch (e) { } }
      const team = teamNames().filter(n => !benched(n));
      const info = (n) => { const p = partyMember(n), lp = livePos[n] || {}; return { dead: lp.at && now() - lp.at < 10000 ? !!lp.IsDead : !!(p && p.IsDead), hp: lp.hp !== undefined ? lp.hp : num(p && p.HpPercent), mp: lp.mp !== undefined ? lp.mp : num(p && p.MpPercent) }; };
      const dead = team.filter(n => info(n).dead);
