  const check = (c) => {
    if (layered || !c || c.objId === myId) return;
    const me = meSnap();
    if (Math.hypot(c.X - me.X, c.Y - me.Y) < 2000 && Math.abs((c.Z || me.Z) - me.Z) > CONFIG.rest.layerDz) layered = true;
  };
  try { snapMobs().forEach(check); snapNpcs().forEach(check); } catch (e) { }
  // bliv streng i 60 s efter sidste fund (monstre på andre etager kan forsvinde ud af syne et øjeblik)
  if (layered) zState.since = now();
  const strict = layered || now() - zState.since < 60000;
  const lim = strict ? CONFIG.rest.zLimitStrict : CONFIG.rest.zLimitOpen;
  if (strict !== zState.layered) note(`height: ${strict ? 'multiple floors here (catacomb/tower) — targets only within ±' + lim : 'normal terrain — targets within ±' + lim}`);
  zState.layered = strict;
  CONFIG.rest.zLimit = lim;
