    return `  state writer: ${tot[0]} ms in ${tot[1]} runs (${(tot[0] / runs).toFixed(1)} ms/run), watched ${SW.watchedRuns}/${SW.runs} runs, avg ${Math.round(SW.bytes / Math.max(1, SW.runs) / 100) / 10} KB; ${parts.join(', ')}`;
