      const lines = [`${new Date().toISOString()} [${Me.Name}] ${secs}s: ticks ${S.ticks} = ${S.tickMs} ms (${(S.tickMs / secs / 10).toFixed(1)}% core), jobs ${T.total} ms sync, ${S.jobs} jobs; ` +
        `snapshot[${N.mode}] ${N.builds} builds (${N.json} json) / ${N.enums} enumerations ${N.ms} ms (${N.n} creatures), ${N.lookups} id lookups + ${N.refs} refs, host snaps ${hostSnap.st.calls} (${hostSnap.st.fails} failed);swarm.pos ${POSF.sent} targeted rounds (${POSF.targeted} sends) + ${POSF.broadcasts} broadcasts, ${Object.keys(posAcct).length} known accounts`];
      T.rows.forEach((r, i) => lines.push(`  ${String(i + 1).padStart(2)}. ${String(r.cost).padStart(6)} ms ${String(r.runs).padStart(5)}x ${r.ms ? 'every ' + r.ms + ' ms' : ''}  ${r.label}`));
