  if (!nx.changeLevel || lvl < nx.changeLevel) { out.status = CP_STATUS.waiting; out.why = `${nx.name} at level ${nx.changeLevel} (now ${lvl})`; out.text = `waiting ${nx.name} @${nx.changeLevel}`; return out; }
