  if (exact.length > 1) return { idx: -1, label: '', why: `${exact.length} buttons are called ${c.name}: ${exact.map(i => L[i]).join(' | ')}` };
  const words = (s) => ' ' + String(s).toLowerCase().replace(/[^a-z' ]/g, ' ').replace(/\s+/g, ' ') + ' ';
