(async () => {
  while (!IsCharacterReady()) await sleep(1000);
  await sleep(1500);

  CONFIG.mainLeader = CONFIG.leader;
  if (CONFIG.teams[Me.Name]) {                  // andet hold: egen leder, ingen auto-regroup til Wasteland
    CONFIG.leader = CONFIG.teams[Me.Name];
    CONFIG.regroup.auto = false;
  }
  rkApplyRole('start');                        // ROLE KINDS (2026-10-10): legacy names unchanged; kinds / auto -> the token for my class
  try {
    File.WriteAllText(`${SWARM_ROOT}\\Logs\\swarm_alive_${Me.Name}.txt`,
      `${new Date().toISOString()} role=${state.role} class=${Me.ClassName} lvl=${Me.Level}\r\n`);
  } catch (e) { }
  if (!state.role) {
    // not in the roster: follow NOBODY (2026-10-06 23:46: the new team's characters took Tank1 as their leader, joined his route walk and
    // used .oren to "catch up" — at level 1). With no leader no team event (route, town, regroup, orders) matches.
    CONFIG.leader = '(not in roster)';
    console.error(`'${Me.Name}' is not in CONFIG.roster — fix the configuration!`);
    return;
  }

  SetWindowTitle(`SWARM ${state.role.toUpperCase()} — ${Me.Name}`);
  resumeActivity().catch(e => logError('resumeActivity', e));
  log(`Ready. Waiting for commands from ${CONFIG.leader} in party chat.`);
})().catch(err => {
  try { File.AppendAllText(SWARM_ROOT + '\\Logs\\swarm_errors.log', `${new Date().toISOString()} startup: ${err.stack}\r\n`); } catch (e) { }
});

globalThis.OnBeforeScriptStop = () => { state.running = false; try { l2sSkillGuard(true); } catch (e) { } };   // CAST LOOP: L2Swarm combat skills this script switched off go back on

// ---------------------------------------------------------------------------
// KORT-KLIK LOGGER  —  når brugeren klikker på kortet: log koordinater + den sti L2Swarm selv går (20 s)
// (så scriptets navigation kan efterligne L2Swarms egen) -> Logs/mapclick_<navn>.log
// ---------------------------------------------------------------------------
globalThis.OnMapClick = (mapX, mapY) => {
  const f = `${SWARM_ROOT}\\Logs\\mapclick_${Me.Name}.log`;
  const t0 = now();
  const line = (m) => appendShared(f, `${new Date().toISOString()} ${m}\r\n`);
  let pathInfo = '';
  try { const p = findPathNow(new Point(Math.round(mapX), Math.round(mapY))); pathInfo = ` FindPath=${p ? p.Count : 'null'} pts`; } catch (e) { pathInfo = ` FindPath error: ${e.message}`; }
  line(`CLICK mapX=${mapX} mapY=${mapY} | I am at ${Math.round(Me.X)},${Math.round(Me.Y)},${Math.round(Me.Z)}${pathInfo} | bot=${IsEnabled} moving=${Me.IsMoving}`);
  note(`map click ${Math.round(mapX)},${Math.round(mapY)} — logging L2Swarm's path`);
  let last = { x: Me.X, y: Me.Y };
  const iv = setInterval(() => {
    const d = Math.hypot(Me.X - last.x, Me.Y - last.y);
    if (d > 30) { line(`  +${((now() - t0) / 1000).toFixed(1)}s ${Math.round(Me.X)},${Math.round(Me.Y)},${Math.round(Me.Z)} moving=${Me.IsMoving}`); last = { x: Me.X, y: Me.Y }; }
    if (now() - t0 > 20000) { SCHED.clear(iv); line(`  end: ${Math.round(Me.X)},${Math.round(Me.Y)} distance to click ${Math.round(Math.hypot(Me.X - mapX, Me.Y - mapY))}`); }
  }, 300);
};
